import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import crypto from 'node:crypto';
import {NativeReviewAdapter,NATIVE_MAPPING} from '../native-adapter.mjs';
import {freshWorld,traverseMain} from '../../source/tests/helpers/world-fixture.mjs';
const root=new URL('../verified/native_home_entries_remaining_1524/',import.meta.url),contract=JSON.parse(fs.readFileSync(new URL('contract.json',root))),travel=JSON.parse(fs.readFileSync(new URL('travel-routes.json',root)));
const masks=Object.fromEntries(Object.entries(contract.masks).map(([k,s])=>{const b=fs.readFileSync(new URL(s.path,root));assert.equal(crypto.createHash('sha256').update(b).digest('hex'),s.sha256);return [k,new Uint8Array(b)];}));
const progression=await traverseMain();
const setup=()=>{const world=freshWorld({runtime:progression.checkpoints.S2}),environment={advance(ms){this.elapsed=(this.elapsed??0)+ms},read(){return {}}};return {world,adapter:new NativeReviewAdapter({world,contract,masks,environment,assets:{}})};};
function walk(s,path){assert.deepEqual(s.foot,path[0]);for(const p of path.slice(1)){const[x,y]=s.foot;assert.equal(s.move(p[0]<x?'left':p[0]>x?'right':p[1]<y?'up':'down').ok,true);}}
test('actual canonical source map exists, correct grid and map identity, wrong map rejected',()=>{const w=freshWorld();assert.equal(w.definition.grid,48);assert.equal(w.definition.maps[NATIVE_MAPPING.canonicalMapId].stageId,'S2');const a=new NativeReviewAdapter({world:w,contract,masks});assert.throws(()=>a.enter(),/REQUIRES_JANGMOK/);w.dispose();});
test('all three verified house enters/returns preserve entire actual canonical snapshot',async()=>{for(const id of ['upper','family','coastal']){const {world,adapter:a}=setup(),before=world.snapshot();a.enter(id);a.openDoor(id);walk(a.session,contract.houses[id].exteriorDoor.approachRoute);a.session.face('up');assert.equal((await a.action()).kind,'enter');a.releaseAction();walk(a.session,contract.floors[a.session.scene].routes.entryArrival_entry);a.session.face('down');assert.equal((await a.action()).kind,'return');assert.deepEqual(a.session.foot,contract.houses[id].exteriorDoor.arrival);assert.equal(a.exit().canonicalSnapshotUnchanged,true);assert.deepEqual(world.snapshot(),before);world.dispose();}});
test('same native session travels upper/family/coastal without canonical tile/encounter writes',()=>{const{world,adapter:a}=setup(),before=world.snapshot();a.enter('upper');walk(a.session,travel.routes.upper__family);walk(a.session,travel.routes.family__coastal);assert.deepEqual(world.snapshot(),before);a.exit();world.dispose();});
test('canonical lock blocks entry, repeat enter blocked, mutation rejected and never overwritten',()=>{const{world,adapter:a}=setup();world.pending=true;assert.throws(()=>a.enter(),/LOCKED/);world.pending=false;a.enter();assert.throws(()=>a.enter(),/ALREADY_ACTIVE/);const old=world.snapshot.bind(world);world.snapshot=()=>({...old(),testChange:true});assert.throws(()=>a.exit(),/CANONICAL_CHANGED/);assert.equal(world.snapshot().testChange,true);a.dispose();world.dispose();});
test('cancel invalidates delayed target; disposal never completes stale portal',async()=>{const{world,adapter:a}=setup();let resolve;a.loadScene=()=>new Promise(r=>resolve=r);a.enter();a.openDoor();walk(a.session,contract.houses.upper.exteriorDoor.approachRoute);a.session.face('up');const pending=a.action();a.cancel();resolve({sha256:contract.sources.upper_1F.sha256});assert.equal((await pending).reason,'STALE');assert.equal(a.session.scene,'exterior');a.exit();world.dispose();});
test('host tick bounded, idle stops gait, no hidden catchup or canonical move',()=>{const{world,adapter:a}=setup(),before=world.snapshot();a.enter();a.frame(5000,null);assert.equal(a.environment.elapsed,50);assert.equal(a.session.moving,false);assert.deepEqual(world.snapshot(),before);a.exit();world.dispose();});
